export function authenticationGraphErrorKey(error) {
	const message = String(error && error.message || error || '');
	if (/accepts 1 to \d+ inputs/i.test(message)) return 'graph.inputCount';
	if (/input must be a JSON object/i.test(message)) return 'graph.invalidObject';
	if (/RUA reports require a policy domain/i.test(message)) return 'graph.ruaDomainMissing';
	if (/RUA.*policy domains?/i.test(message)) return 'graph.ruaDomainMismatch';
	if (/inputs refer to different domains/i.test(message)) return 'graph.domainMismatch';
	if (/requires a root domain/i.test(message)) return 'graph.rootMissing';
	if (/invalid node label/i.test(message)) return 'graph.invalidNode';
	if (/exceeds .*limit/i.test(message)) return 'graph.safetyLimit';
	return 'graph.unexpected';
}

for (const [language, sections] of Object.entries(AUTHENTICATION_GRAPH_DISPLAY_MESSAGES)) {
	const messages = AUTHENTICATION_GRAPH_MESSAGES[language];
	for (const [section, values] of Object.entries(sections)) {
		for (const [key, value] of Object.entries(values)) messages[`${section}.${key}`] = value;
	}
}

for (const [language, messages] of Object.entries(AUTHENTICATION_GRAPH_ERROR_MESSAGES)) {
	Object.assign(AUTHENTICATION_GRAPH_MESSAGES[language], messages);
}

